var n=`0438-lefse`;var o=`world-0438`;var i=`NO`;var r=`northern-europe`;var a=4;var s=52;var l={en:`Lefse`,ua:`Лефсе`};var u={en:`A traditional dish from Norway, centered on potato, all-purpose flour, heavy cream. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: картопля, пшеничне борошно універсальне, вершки високої жирності. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`potato`,500,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`all-purpose-flour`,210,`g`],[`unsalted-butter`,40,`g`],[`heavy-cream`,110,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 13 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 13 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:13,i:[]}];var m={slug:n,id:o,country:`NO`,region:r,servings:4,minutes:52,title:l,text:u,steps:d};export{i as country,m as default,o as id,s as minutes,r as region,a as servings,n as slug,d as steps,u as text,l as title};